const enabled = process.env.GODSEYE_INNGEST_LAB === "enabled";
const binary = resolve("artifacts/tools/inngest-1.52.0/inngest.exe");
const pause = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

async function unusedPort() {
  const server = createServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Native lab port unavailable");
  await new Promise<void>((done, reject) =>
    server.close((error) => (error ? reject(error) : done())),
  );
  return address.port;
}
async function stop(child: ChildProcess) {
  if (child.exitCode !== null || child.signalCode !== null) return;
  const closed = once(child, "close");
  child.kill("SIGTERM");
  await closed;
}
async function waitFor(check: () => Promise<boolean>, message: string, ms = 45000) {
  const deadline = Date.now() + ms;
  while (Date.now() < deadline) {
    if (await check()) return;
    await pause(100);
  }
  throw new Error(message);
}

describe.runIf(enabled)("actual local per-cell Inngest SDK composition", () => {
  let fixture: JobsFixture | undefined;
  let root: string | undefined;
  const children: ChildProcess[] = [];
  const listeners: ReturnType<typeof serve>[] = [];
  const backends: BackendFixture[] = [];
  afterEach(async () => {
    for (const child of children.splice(0)) await stop(child);
    for (const server of listeners.splice(0))
      await new Promise<void>((done, reject) =>
        server.close((error) => (error ? reject(error) : done())),
      );
    for (const backend of backends.splice(0)) await backend.close();
    await fixture?.store.close();
    fixture = undefined;
    if (root) await rm(root, { recursive: true, force: true });
    root = undefined;
  });

  it("T-E06-L01 delivers app publications through two real isolated engines into their own terminal Foundation jobs", async () => {
    expect(existsSync(binary), "Install the checksum-pinned project-local Inngest tool first").toBe(
      true,
    );
    root = await mkdtemp(join(tmpdir(), "godseye-inngest-native-"));
    const sourceCells = new Map<string, BackendFixture>();
    fixture = await jobsFixture({
      timeoutMs: 5000,
      applicationEventLoader: async (authority, id) => {
        const source = sourceCells.get(authority.producerId);
        if (
          !source ||
          source.scope.projectId !== authority.projectId ||
          source.scope.environmentId !== authority.environmentId
        )
          return undefined;
        return source.runtime.readJobEvent(id);
      },
    });
    const activeFixture = fixture;
    const secondEnvironment = fixture.secondProject.environments.find(
      (item) => item.kind === "development",
    );
    if (!secondEnvironment) throw new Error("Second native cell missing");
    const definitions = [
      await fixture.register({ trigger: { kind: "event", eventType: "document.updated" } }),
      await fixture.jobs().registerDefinition(
        fixture.freshOwner(),
        {
          projectId: fixture.secondProject.id,
          environmentId: secondEnvironment.id,
          expectedEnvironmentRevision: secondEnvironment.revision,
          name: "native-other-event",
          handler: "fixture.other",
          trigger: { kind: "event", eventType: "document.updated" },
          effectPolicy: "idempotent",
          limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
        },
        randomUUID(),
      ),
    ];
    const cells: Array<{
      backend: BackendFixture;
      cell: ReturnType<typeof createInngestCell>;
      baseUrl: string;
      sdkUrl: string;
      eventKey: string;
      signingKey: string;
      diagnostics: () => string;
    }> = [];

    for (const [index, definition] of definitions.entries()) {
      const ports = await Promise.all(Array.from({ length: 5 }, () => unusedPort()));
      const [enginePort, gatewayPort, gatewayGrpcPort, executorGrpcPort, workerPort] = ports;
      const baseUrl = `http://127.0.0.1:${enginePort}`;
      const sdkUrl = `http://127.0.0.1:${workerPort}/api/inngest`;
      const eventKey = randomBytes(32).toString("hex");
      const signingKey = randomBytes(32).toString("hex");
      let cell: ReturnType<typeof createInngestCell>;
      const backend = await backendFixture({
        scope: { projectId: definition.projectId, environmentId: definition.environmentId },
        jobs: { transport: { send: (event, signal) => cell.transport.send(event, signal) } },
      });
      backends.push(backend);
      sourceCells.set(backend.store.id, backend);
      backend.lifecycle.epoch = 1;
      cell = createInngestCell({
        id: `native-cell-${index}`,
        authority: { ...backend.scope, producerId: backend.store.id },
        jobs: fixture.jobs(),
        baseUrl,
        sdkUrl,
        eventKey,
        signingKey,
        pollIntervalMs: 100,
        maxObservations: 100,
      });
      const workerRequests: string[] = [];
      const server = serve({
        fetch: async (request) => {
          const response = await cell.app.fetch(request);
          workerRequests.push(
            `${request.method} ${new URL(request.url).host} host=${request.headers.get("host")} status=${response.status}`,
          );
          return response;
        },
        port: workerPort,
        hostname: "127.0.0.1",
      });
      listeners.push(server);
      if (!server.listening) await once(server, "listening");
      const directory = join(root, `cell-${index}`);
      await mkdir(directory);
      const child = spawn(
        binary,
        [
          "--log-level",
          "info",
          "start",
          "--host",
          "127.0.0.1",
          "--port",
          String(enginePort),
          "--connect-gateway-port",
          String(gatewayPort),
          "--connect-gateway-grpc-port",
          String(gatewayGrpcPort),
          "--connect-executor-grpc-port",
          String(executorGrpcPort),
          "--sqlite-dir",
          directory,
          "--sdk-url",
          sdkUrl,
          "--event-key",
          eventKey,
          "--signing-key",
          signingKey,
          "--queue-workers",
          "10",
          "--tick",
          "100",
        ],
        { cwd: directory, stdio: ["ignore", "pipe", "pipe"] },
      );
      children.push(child);
      let diagnostics = "";
      const observe = (chunk: Buffer) => {
        diagnostics = (
          diagnostics +
          chunk
            .toString()
            .replaceAll(eventKey, "[fixture-material]")
            .replaceAll(signingKey, "[fixture-material]")
        ).slice(-12000);
      };
      child.stdout?.on("data", observe);
      child.stderr?.on("data", observe);
      await waitFor(async () => {
        if (child.exitCode !== null)
          throw new Error(`Native engine ${index} exited before readiness`);
        try {
          return (await fetch(`${baseUrl}/health`, { signal: AbortSignal.timeout(1000) })).ok;
        } catch {
          return false;
        }
      }, `Native engine ${index} readiness deadline`);
      const registration = await fetch(sdkUrl, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        signal: AbortSignal.timeout(10000),
      });
      const registered: unknown = await registration.json();
      if (!registration.ok)
        throw new Error(
          `Native worker registration ${registration.status}: ${JSON.stringify(registered)}`,
        );
      cells.push({
        backend,
        cell,
        baseUrl,
        sdkUrl,
        eventKey,
        signingKey,
        diagnostics: () => `${diagnostics}; worker=${workerRequests.join(";")}`,
      });
    }

    for (const [index, entry] of cells.entries()) {
      const registered = await entry.backend.register();
      const key = randomUUID();
      const publication = {
        userId: registered.user.id,
        type: "document.updated",
        payload: { cell: index },
        idempotencyKey: key,
      };
      await entry.backend.runtime.publishEvent(publication);
      await entry.backend.runtime.publishEvent(publication);
      const flushed = await entry.backend.runtime.flushJobs();
      if (flushed.delivered !== 1)
        throw new Error(
          `Native source acknowledgement missing: ${JSON.stringify(flushed)}; ${entry.diagnostics()}`,
        );
      expect(flushed).toMatchObject({ delivered: 1, pending: 0 });
    }

    await waitFor(
      async () => {
        await activeFixture.work("native-inngest-foundation");
        const runs = (await activeFixture.jobs().overview(activeFixture.freshOwner())).runs;
        return runs.length === 2 && runs.every((run) => run.state === "succeeded");
      },
      "Real Inngest publications never reached terminal Foundation results",
      60000,
    ).catch(async (error: unknown) => {
      const runs = (await activeFixture.jobs().overview(activeFixture.freshOwner())).runs;
      throw new Error(
        `${error instanceof Error ? error.message : "Native lab failed"}; runs=${JSON.stringify(runs)}; engine=${cells.map((entry) => entry.diagnostics()).join("\n")}`,
      );
    });
    const runs = (await fixture.jobs().overview(fixture.freshOwner())).runs;
    expect(runs.map((run) => run.definitionId).sort()).toEqual(
      definitions.map((definition) => definition.id).sort(),
    );
    expect(fixture.handler.calls.map((call) => call.environmentId)).toEqual([
      definitions[0]?.environmentId,
    ]);
    expect(fixture.other.calls.map((call) => call.environmentId)).toEqual([
      definitions[1]?.environmentId,
    ]);
    expect(fixture.handler.calls[0]?.event?.payload).toEqual({ cell: 0 });
    expect(fixture.other.calls[0]?.event?.payload).toEqual({ cell: 1 });

    // Correct event authority for A cannot send into B's engine, nor can unsigned callers invoke its SDK.
    const [firstCell, secondCell] = cells;
    if (!firstCell || !secondCell) throw new Error("Two running native cells are required");
    const foreign = await fetch(`${secondCell.baseUrl}/e/${firstCell.eventKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: "godseye/application.event", data: {} }),
    });
    expect(foreign.status).toBe(401);
    const unsigned = await fetch(secondCell.sdkUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ event: {} }),
    });
    expect(unsigned.status).toBe(401);
    expect((await fixture.jobs().overview(fixture.freshOwner())).runs).toHaveLength(2);
  }, 180000);
});
